from pathlib import Path
from typing import Any, Optional

import polars as pl

from sglang.srt.debug_utils.dump_loader import ValueWithMeta


def _render_polars_as_text(df: pl.DataFrame, *, title: Optional[str] = None) -> str:
    """Render a Polars DataFrame as a simple text table.

    The result always includes the column names (even for an empty DataFrame)
    and, when provided, the ``title`` as the first line.
    """
    columns: list[str] = list(df.columns)

    # Build the matrix of stringified cells (header + rows).
    header: list[str] = columns
    rows: list[list[str]] = [
        ["" if value is None else str(value) for value in row]
        for row in df.iter_rows()
    ]

    widths: list[int] = [len(col) for col in header]
    for row in rows:
        for i, cell in enumerate(row):
            widths[i] = max(widths[i], len(cell))

    def _format_row(cells: list[str]) -> str:
        return " | ".join(
            cell.ljust(widths[i]) for i, cell in enumerate(cells)
        ).rstrip()

    lines: list[str] = []
    if title is not None:
        lines.append(title)

    if columns:
        lines.append(_format_row(header))
        lines.append("-+-".join("-" * w for w in widths))
        for row in rows:
            lines.append(_format_row(row))
    return "\n".join(lines)


def _extract_parallel_info(row_data: dict[str, Any], info: dict[str, Any]) -> None:
    """Populate ``row_data`` with 'rank/size' entries from a parallel-info dict.

    For each ``{base}_rank`` key that has a matching ``{base}_size`` key, sets
    ``row_data[base] = "{rank}/{size}"``. No-op when ``info`` is empty or
    contains an ``error`` key. ``_rank`` keys without a matching ``_size`` key
    are skipped.
    """
    if not info or "error" in info:
        return

    for key in info:
        if not key.endswith("_rank"):
            continue
        base: str = key[: -len("_rank")]
        size_key: str = f"{base}_size"
        if size_key not in info:
            continue
        row_data[base] = f"{info[key]}/{info[size_key]}"


def _collect_rank_info(
    df: pl.DataFrame, dump_dir: Path
) -> Optional[list[dict[str, Any]]]:
    """Collect per-rank parallel topology from ``input_ids`` dumps.

    Returns ``None`` when no ``input_ids`` rows exist. Otherwise returns a
    deduplicated (one per rank) list of dicts, each with ``rank`` and any
    parallel dimension entries (e.g. ``tp='0/2'``) read from the
    ``sglang_parallel_info`` metadata of the corresponding ``.pt`` file.
    """
    if "name" not in df.columns:
        return None

    matching = df.filter(pl.col("name") == "input_ids")
    if matching.height == 0:
        return None

    dump_dir = Path(dump_dir)
    result: list[dict[str, Any]] = []
    seen_ranks: set[Any] = set()

    for row in matching.iter_rows(named=True):
        rank = row.get("rank")
        if rank in seen_ranks:
            continue
        seen_ranks.add(rank)

        row_data: dict[str, Any] = {"rank": rank}
        info = _read_parallel_info(dump_dir, row.get("filename"))
        _extract_parallel_info(row_data, info)
        result.append(row_data)

    return result


def _read_parallel_info(dump_dir: Path, filename: Optional[str]) -> dict[str, Any]:
    if not filename:
        return {}
    value_with_meta = ValueWithMeta.load(dump_dir / filename)
    info = value_with_meta.meta.get("sglang_parallel_info")
    return info if isinstance(info, dict) else {}


def _collect_input_ids_and_positions(
    df: pl.DataFrame,
    dump_dir: Path,
    *,
    tokenizer: Any = None,
) -> Optional[list[dict[str, Any]]]:
    """Collect input token ids and positions from dumps.

    Returns ``None`` when no ``input_ids``/``positions`` rows exist. Otherwise
    returns a list of dicts, one per ``(step, rank)`` pair, each with ``step``,
    ``rank``, ``num_tokens``, ``input_ids`` (str) and ``positions`` (str). When
    ``tokenizer`` is provided, also adds ``decoded_text`` =
    ``repr(tokenizer.decode(ids, skip_special_tokens=False))``.
    """
    if "name" not in df.columns:
        return None

    matching = df.filter(pl.col("name").is_in(["input_ids", "positions"]))
    if matching.height == 0:
        return None

    dump_dir = Path(dump_dir)

    # Group by (step, rank) preserving encounter order.
    grouped: dict[tuple[Any, Any], dict[str, Any]] = {}
    order: list[tuple[Any, Any]] = []
    for row in matching.iter_rows(named=True):
        key = (row.get("step"), row.get("rank"))
        if key not in grouped:
            grouped[key] = {}
            order.append(key)
        grouped[key][row["name"]] = row.get("filename")

    result: list[dict[str, Any]] = []
    for step, rank in order:
        filenames = grouped[(step, rank)]

        ids_value = _load_value(dump_dir, filenames.get("input_ids"))
        positions_value = _load_value(dump_dir, filenames.get("positions"))

        ids_list = _to_list(ids_value)

        entry: dict[str, Any] = {
            "step": step,
            "rank": rank,
            "num_tokens": len(ids_list),
            "input_ids": str(ids_list),
            "positions": str(_to_list(positions_value)),
        }
        if tokenizer is not None:
            entry["decoded_text"] = repr(
                tokenizer.decode(ids_list, skip_special_tokens=False)
            )
        result.append(entry)

    return result


def _load_value(dump_dir: Path, filename: Optional[str]) -> Any:
    if not filename:
        return None
    return ValueWithMeta.load(dump_dir / filename).value


def _to_list(value: Any) -> list[Any]:
    if value is None:
        return []
    tolist = getattr(value, "tolist", None)
    if callable(tolist):
        value = tolist()
    if isinstance(value, (list, tuple)):
        return list(value)
    return [value]
