def _rows_to_df(rows: list[dict[str, Any]]) -> pl.DataFrame:
    """Build a DataFrame from row dicts, preserving key order and filling gaps."""
    columns: list[str] = []
    for row in rows:
        for key in row:
            if key not in columns:
                columns.append(key)
    normalized = [{col: row.get(col) for col in columns} for row in rows]
    return pl.DataFrame(normalized, schema=[(col, pl.Object) for col in columns])


